(* [comment removed for export] *)
Definition nhullA (RNG : footprint) (m : amem) (LB : list ablock) (A n : Z) : Prop :=
  shullA RNG m LB A n \/ (exists p B N, In (mkABlock (ABHeap p) B N) LB /\ B <= A /\ A + n <= B + N).

