(* [comment removed for export] *)
Definition fse_read_postA (L : alayout) (RNG : footprint)
    (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (FR : bvmap 5 word) (fc : bv 32)
    (st : astate) (LB : list ablock) (SPV NC MSVP TLP : Z) (rt0 rt : list Z) (msv tl n lo : Z) (m : amem)
    : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra (Z_to_bv 64 SPV) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 n) a1 a2 a3 a4 a5 a6 a7
                 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             FR (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ mem_inv bsegs m' /\ stk bsegs m' lo SPV
    /\ magree bsegs (fun a => aclient_addr CI LB SPV a /\ ~ (NC <= a < NC + 2 * zlen rt0)
                              /\ ~ (MSVP <= a < MSVP + 4) /\ ~ (TLP <= a < TLP + 4)) m m'
    /\ AHEAP AI L RNG st LB m'
    /\ u8arr bsegs m' NC (u16s (map (Z_to_bv 64) rt))
    /\ rw_cells bsegs m' MSVP [C4 (Z_to_bv 64 msv)]
    /\ rw_cells bsegs m' TLP [C4 (Z_to_bv 64 tl)].

(* [comment removed for export] *)
Definition fse_read_resA (res0 : res (list Z * Z * Z * Z)) (m' : amem) (rt0 : list Z) (NC MSVP TLP r : Z) : Prop :=
  match res0 with
  | Ok (rt, msv, tl, n) => r = n /\ u8arr bsegs m' NC (u16s (map (Z_to_bv 64) rt))
                           /\ rw_cells bsegs m' MSVP [C4 (Z_to_bv 64 msv)] /\ rw_cells bsegs m' TLP [C4 (Z_to_bv 64 tl)]
  | Err e => r = 2^64 - e /\ 0 < e < 120
             /\ (exists rt' msv' tl', length rt' = length rt0 /\ u8arr bsegs m' NC (u16s (map (Z_to_bv 64) rt'))
                                     /\ rw_cells bsegs m' MSVP [C4 (Z_to_bv 64 msv')] /\ rw_cells bsegs m' TLP [C4 (Z_to_bv 64 tl')])
  | _ => False
  end.

Definition fse_readr_postA (L : alayout) (RNG : footprint)
    (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (FR : bvmap 5 word) (fc : bv 32)
    (st : astate) (LB : list ablock) (SPV NC MSVP TLP : Z) (rt0 : list Z) (res0 : res (list Z * Z * Z * Z)) (lo : Z) (m : amem)
    : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 (r : Z) m',
    ms' = MS (mkR ra (Z_to_bv 64 SPV) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 r) a1 a2 a3 a4 a5 a6 a7
                 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             FR (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ mem_inv bsegs m' /\ stk bsegs m' lo SPV
    /\ magree bsegs (fun a => aclient_addr CI LB SPV a /\ ~ (NC <= a < NC + 2 * zlen rt0)
                              /\ ~ (MSVP <= a < MSVP + 4) /\ ~ (TLP <= a < TLP + 4)) m m'
    /\ AHEAP AI L RNG st LB m'
    /\ fse_read_resA res0 m' rt0 NC MSVP TLP r.

Definition fse_readk_postA (L : alayout) (RNG : footprint)
    (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (FR : bvmap 5 word) (fc : bv 32)
    (st : astate) (LB : list ablock) (SPV NC MSVP TLP : Z) (rt0 buf : list Z) (msv0 lo : Z) (m : amem)
    : machine_state -> Prop :=
  fse_readr_postA L RNG ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc st LB SPV NC MSVP TLP rt0 (read_ncount rt0 msv0 buf) lo m.

(* [comment removed for export] *)
Lemma readr_of_ok : forall L RNG ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc st LB SPV NC MSVP TLP rt0 rt msv tl n lo m ms',
  fse_read_postA L RNG ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc st LB SPV NC MSVP TLP rt0 rt msv tl n lo m ms' ->
  fse_readr_postA L RNG ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc st LB SPV NC MSVP TLP rt0 (Ok (rt, msv, tl, n)) lo m ms'.
